// Author: MiYu. Typed callback wrappers retain a shared scheduler and dispatch binary functions.
#include "jass_binary_callbacks.h"
#include <stdexcept>

namespace war3 {
JassBinaryCallbacks::JassBinaryCallbacks(jass::Runtime& owner,std::shared_ptr<const JassBinaryProgram> program,JassBinaryIndex index,JassBinaryHost host):program_(std::move(program)),index_(std::move(index)),host_(std::move(host)){
    if(!program_ || !owner.ready())throw std::runtime_error("2SAJ callbacks require an initialized owner");std::string declarations;for(auto& type:owner.module().program().types())declarations+="type "+type.name+" extends "+type.parent+"\n";size_t number=0;for(auto& [name,bounds]:index_.functions){auto [start,end]=bounds;if(start>=end || end>=program_->instructions.size())throw std::runtime_error("Invalid 2SAJ callback bounds");auto& entry=program_->instructions[start];if((entry.r1!=0 && entry.r1!=8) || program_->instructions[start+1].opcode==8)continue;if(number>=65536)throw std::runtime_error("2SAJ callback budget exceeded");auto wrapper="binaryCallback"+std::to_string(number++);names_.emplace(name,wrapper);declarations+="native "+wrapper+" takes nothing returns "+(entry.r1==8?"boolean":"nothing")+"\n";}
    auto module=jass::Module::compile(jass::Program::parse({{"2saj-callbacks.j",std::move(declarations),"2SAJ"}}));runtime_=std::make_unique<jass::Runtime>(std::move(module));runtime_->shareThreads(owner);runtime_->scopedSharedDestruction();host_.codeReference=[this](const std::string& name){return reference(name);};for(auto& [name,wrapper]:names_){reverse_.emplace(runtime_->module().functionId(wrapper)+1,name);auto result=program_->instructions[index_.functions.at(name).first].r1;runtime_->bind(wrapper,[this,name,result](auto& vm,auto){auto value=runJass2Function(*program_,index_,name,host_);if(result==0){if(value.type!=0)throw std::runtime_error("2SAJ callback result differs");return vm.nothing();}if(value.type!=8 || value.bits>1)throw std::runtime_error("2SAJ predicate result differs");return vm.boolean(value.bits!=0);});}runtime_->initialize();
}
std::optional<std::string> JassBinaryCallbacks::name(const jass::Value& code) const{
    if(code.codeOwner!=runtime_.get())return {};auto token=runtime_->lifetimeToken();auto alive=code.codeLifetime.lock();if(!alive || !alive->alive || code.codeLifetime.owner_before(token) || token.owner_before(code.codeLifetime) || code.type!=runtime_->module().typeId("code") || !code.bits)throw std::runtime_error("Invalid 2SAJ callback reference");auto found=reverse_.find(code.bits);if(found!=reverse_.end())return found->second;throw std::runtime_error("Unknown 2SAJ callback reference");
}
JassBinaryNativeValue JassBinaryCallbacks::reference(const std::string& name){auto found=names_.find(name);if(found==names_.end())throw std::runtime_error("Unsupported 2SAJ callback signature: "+name);auto id=runtime_->module().functionId(found->second);jass::Value code{runtime_->module().typeId("code"),id+1,{},runtime_.get(),runtime_->lifetimeToken()};return {3,code.bits,{},code};}
}
